#include <print>
#include <string>

class Score {
public:
    void add(int n) {
        if (n < 0) return;
        done_ += n;
        if (done_ > total_) done_ = total_;
    }
    int done() const { return done_; }
    int left() const { return total_ - done_; }
private:
    std::string subject_ = "未命名";
    int total_ = 100;
    int done_ = 0;
};

int main() {
    Score s;
    s.add(30);
    std::println("进度 = {}", s.done());
    s.done_ = 9999;   // 编译不过：绕过按钮之后每个数字都不再可信，锁起来更安全
    return 0;
}

